mapper.select:
/* 고객별 통계 [6050] - 거래규모 목록 데이터 */ /* StatUserMapper.select1List */ WITH VW_TASK AS ( SELECT A.INPT_MST_SRNO , A.ACTL_FX_REFNO , A.INPT_RCP_DT , B.XPBY_COL_CTR_CUCD AS FC_CUCD , B.XPBY_COL_AM AS AI_INPT_BUY_AM , SUBSTR(A.INPT_RCP_DT,1,6) AS INPT_RCP_YM FROM CSPD001TM A, ( SELECT FX_ACNO AS ACTL_FX_REFNO , XPBY_COL_CTR_CUCD AS XPBY_COL_CTR_CUCD , NVL(INPT_FAXC_AM, XPBY_COL_AM) AS XPBY_COL_AM , CUS_ENG_NM , CSNO , XPO_CVRG_MK_SQ AS FX_REFNO_SRNO FROM CSPD201TM UNION ALL SELECT FX_ACNO AS ACTL_FX_REFNO , TDOC_RCP_CUCD AS XPBY_COL_CTR_CUCD , NVL(INPT_FAXC_AM, TDOC_RCP_AM) AS XPBY_COL_AM , CUS_ENG_NM , CSNO , TDOC_RCP_SRNO AS FX_REFNO_SRNO FROM CSPD202TM ) B WHERE A.ACTL_FX_REFNO = B.ACTL_FX_REFNO(+) AND A.FX_REFNO_SRNO = B.FX_REFNO_SRNO(+) AND A.INPT_ATMC_BIZ_DSCD = #{inptAtmcBizDscd} AND TO_NUMBER(A.INPT_RCP_DT) BETWEEN TO_NUMBER(REPLACE(#{schSdate},'-','')) AND TO_NUMBER(REPLACE(#{schEdate} ,'-',''))
AND B.CSNO = #{aiInptCsno}
) SELECT TO_CHAR(TO_DATE(A.INPT_RCP_YM, 'YYYYMM'), 'YYYY-MM') AS INPT_RCP_YM, COUNT(*) AS CNT, NVL(SUM(A.AI_INPT_BUY_AM),0) AS AI_INPT_BUY_AM FROM VW_TASK A GROUP BY A.INPT_RCP_YM ORDER BY A.INPT_RCP_YM ASC

/* 고객별 통계 [6050] - Pending, Block 이력 목록 데이터 */ /* StatUserMapper.select2List */ WITH VW_TASK AS ( /* Block 과 Pending 이력이 있는 심사번호목록 */ SELECT A.INPT_MST_SRNO , A.ACTL_FX_REFNO , A.INPT_RCP_DT , A.FX_REFNO_SRNO , C.XPBY_COL_CTR_CUCD AS FC_CUCD , C.XPBY_COL_AM AS AI_INPT_BUY_AM , B.AI_INPT_ACVT_CD , (SELECT AI_INPT_CMN_CD_NM FROM CSPD112TI WHERE AI_INPT_GRP_CD = '290' AND AI_INPT_CMN_CD = B.AI_INPT_ACVT_STS_CD) AS AI_INPT_ACVT_NM FROM CSPD001TM A, CSPD008TH B, ( SELECT FX_ACNO AS ACTL_FX_REFNO , XPBY_COL_CTR_CUCD AS XPBY_COL_CTR_CUCD , NVL(INPT_FAXC_AM, XPBY_COL_AM) AS XPBY_COL_AM , CUS_ENG_NM , CSNO , XPO_CVRG_MK_SQ AS FX_REFNO_SRNO FROM CSPD201TM UNION ALL SELECT FX_ACNO AS ACTL_FX_REFNO , TDOC_RCP_CUCD AS XPBY_COL_CTR_CUCD , NVL(INPT_FAXC_AM, TDOC_RCP_AM) AS XPBY_COL_AM , CUS_ENG_NM , CSNO , TDOC_RCP_SRNO AS FX_REFNO_SRNO FROM CSPD202TM ) C WHERE A.INPT_MST_SRNO = B.INPT_MST_SRNO(+) AND A.ACTL_FX_REFNO = C.ACTL_FX_REFNO(+) AND A.FX_REFNO_SRNO = C.FX_REFNO_SRNO(+) AND A.INPT_ATMC_BIZ_DSCD = #{inptAtmcBizDscd} AND B.AI_INPT_ACVT_STS_CD IN ('130','140') AND TO_NUMBER(A.INPT_RCP_DT) BETWEEN TO_NUMBER(REPLACE(#{schSdate},'-','')) AND TO_NUMBER(REPLACE(#{schEdate} ,'-',''))
AND C.CSNO = #{aiInptCsno}
) SELECT A.* FROM VW_TASK A ORDER BY A.INPT_MST_SRNO DESC, A.INPT_RCP_DT ASC

/* 고객별 통계 [6050] - 차트 공통목록 데이터 (건수) */ /* StatUserMapper.selectChartList3 */ SELECT ROWNUM AS NUM, A.* FROM ( SELECT A.* FROM ( SELECT INPT_SANCTION_DAT_TXT AS TITLE, SUM(CASE WHEN A.INPT_ATMC_BIZ_DSCD = '1' THEN 1 ELSE 0 END) AS IMP_CNT, SUM(CASE WHEN A.INPT_ATMC_BIZ_DSCD = '2' THEN 1 ELSE 0 END) AS EXP_CNT, COUNT(*) AS TOT_CNT FROM ( SELECT A.INPT_MST_SRNO , A.INPT_SANCTION_DAT_TXT , MAX(B.INPT_ATMC_BIZ_DSCD) AS INPT_ATMC_BIZ_DSCD , COUNT(*) AS CNT FROM CSPD004TF A, CSPD001TM B, ( SELECT FX_ACNO AS ACTL_FX_REFNO, XPO_CVRG_MK_SQ AS FX_REFNO_SRNO, XPBY_COL_CTR_CUCD AS XPBY_COL_CTR_CUCD, XPBY_COL_AM AS XPBY_COL_AM, CUS_ENG_NM, CSNO FROM CSPD201TM -- 수출테이블
WHERE CSNO = #{aiInptCsno}
UNION ALL
SELECT FX_ACNO AS ACTL_FX_REFNO, TDOC_RCP_SRNO AS FX_REFNO_SRNO, TDOC_RCP_CUCD AS XPBY_COL_CTR_CUCD, TDOC_RCP_AM AS XPBY_COL_AM, CUS_ENG_NM, CSNO FROM CSPD202TM -- 수입테이블
WHERE CSNO = #{aiInptCsno}
) C WHERE A.INPT_MST_SRNO = B.INPT_MST_SRNO AND B.ACTL_FX_REFNO = C.ACTL_FX_REFNO(+) AND B.FX_REFNO_SRNO = C.FX_REFNO_SRNO(+) AND A.INPT_SANCTION_NO = #{inptSanctionNo} AND B.INPT_ATMC_BIZ_DSCD = #{inptAtmcBizDscd} /* 검색 - (업무구분) 1 - 수입, 2 - 수출 */ AND TO_NUMBER(B.INPT_RCP_DT) BETWEEN TO_NUMBER(REPLACE(#{schSdate},'-','')) AND TO_NUMBER(REPLACE(#{schEdate} ,'-','')) AND A.INPT_SANCTION_DAT_TXT IS NOT NULL GROUP BY A.INPT_MST_SRNO, A.INPT_SANCTION_DAT_TXT ) A GROUP BY A.INPT_SANCTION_DAT_TXT ) A WHERE A.TOT_CNT > 0 ORDER BY A.TOT_CNT DESC ) A WHERE ROWNUM <= #{recordCountPerPage}

/* 고객별 통계 [6050] - 차트 공통목록 데이터 (금액) */ /* StatUserMapper.selectChartList2 */ SELECT ROWNUM AS NUM, A.* FROM ( SELECT A.* FROM ( SELECT INPT_SANCTION_DAT_TXT AS TITLE, NVL(SUM(CASE WHEN A.INPT_ATMC_BIZ_DSCD = '1' THEN A.AI_INPT_BUY_AM ELSE 0 END),0) AS IMP_AI_INPT_BUY_AM, NVL(SUM(CASE WHEN A.INPT_ATMC_BIZ_DSCD = '2' THEN A.AI_INPT_BUY_AM ELSE 0 END),0) AS EXP_AI_INPT_BUY_AM, NVL(SUM(A.AI_INPT_BUY_AM),0) AS AI_INPT_BUY_AM FROM ( SELECT A.INPT_MST_SRNO , A.INPT_SANCTION_DAT_TXT , B.ACTL_FX_REFNO , B.FX_REFNO_SRNO , MAX(B.INPT_ATMC_BIZ_DSCD) AS INPT_ATMC_BIZ_DSCD , SUM(C.XPBY_COL_AM) AS AI_INPT_BUY_AM FROM CSPD004TF A, CSPD001TM B , () C WHERE A.INPT_MST_SRNO = B.INPT_MST_SRNO AND B.ACTL_FX_REFNO = C.ACTL_FX_REFNO(+) AND B.FX_REFNO_SRNO = C.FX_REFNO_SRNO(+) AND A.INPT_SANCTION_NO = #{inptSanctionNo} AND B.INPT_ATMC_BIZ_DSCD = #{inptAtmcBizDscd} /* 검색 - (업무구분) 1 - 수입, 2 - 수출 */ AND TO_NUMBER(B.INPT_RCP_DT) BETWEEN TO_NUMBER(REPLACE(#{schSdate},'-','')) AND TO_NUMBER(REPLACE(#{schEdate} ,'-','')) AND A.INPT_SANCTION_DAT_TXT IS NOT NULL
AND C.CSNO = #{aiInptCsno} /* 검색 - 고객번호 */
GROUP BY A.INPT_MST_SRNO, A.INPT_SANCTION_DAT_TXT , B.FX_REFNO_SRNO, B.ACTL_FX_REFNO ) A GROUP BY A.INPT_SANCTION_DAT_TXT ) A WHERE A.AI_INPT_BUY_AM > 0 ORDER BY A.AI_INPT_BUY_AM DESC ) A WHERE ROWNUM <= #{recordCountPerPage}
